"use client";

import { useId, useState } from "react";

import { PlayerPlayFilledIcon, RefreshIcon } from "@/components/blocks/parts/icons";
import { Switch } from "@/components/motion/switch";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";

import { BlockFrame } from "../parts/block-frame";
import { ScaleIcon } from "./icons";
import { AnswerPane } from "./model-arena/answer-pane";
import { OWN_PROMPT_ANSWERS, PAIRS, SAMPLES, START_RATINGS } from "./model-arena/data";
import { Leaderboard, type Standing } from "./model-arena/leaderboard";
import { words } from "./shared/answer";
import { modelById } from "./shared/models";
import { useWordStream } from "./shared/use-word-stream";

type Vote = "A" | "B" | "tie";

const STEP = 12;

/**
 * A blind side-by-side test. One prompt goes to two hidden models whose
 * answers stream at the same pace; the person votes for the better one, then
 * the card reveals who wrote each and moves the leaderboard.
 */
export function ModelArena({ className }: { className?: string }) {
  const titleId = useId();
  const blindId = useId();
  const [prompt, setPrompt] = useState(SAMPLES[0]!.prompt);
  const [answers, setAnswers] = useState<[string, string]>(SAMPLES[0]!.answers);
  const [round, setRound] = useState(0);
  const [blind, setBlind] = useState(true);
  const [vote, setVote] = useState<Vote | null>(null);
  const [standings, setStandings] = useState<Standing[]>(START_RATINGS);
  const left = useWordStream({ delay: 300 });
  const right = useWordStream({ delay: 300 });

  const pair = PAIRS[round % PAIRS.length]!;
  const [modelA, modelB] = [modelById(pair[0]), modelById(pair[1])];
  // Swap which style each model writes in every other round, so style never gives a model away.
  const [textA, textB] = round % 2 === 0 ? answers : [answers[1], answers[0]];
  const started = left.status !== "idle";
  const finished = !left.busy && !right.busy && started;
  const revealed = !blind || vote !== null;

  const run = (nextPrompt = prompt) => {
    const value = nextPrompt.trim();
    if (!value || left.busy || right.busy) return;
    const sample = SAMPLES.find((item) => item.prompt === value);
    const nextAnswers = sample ? sample.answers : OWN_PROMPT_ANSWERS;
    setAnswers(nextAnswers);
    setVote(null);
    const [a, b] = round % 2 === 0 ? nextAnswers : [nextAnswers[1], nextAnswers[0]];
    left.start(words(a).length);
    right.start(words(b).length);
  };

  const cast = (choice: Vote) => {
    setVote(choice);
    setStandings((list) =>
      list.map((row) => {
        const isA = row.id === modelA.id;
        const isB = row.id === modelB.id;
        if (!isA && !isB) return row;
        const delta = choice === "tie" ? 0 : (choice === "A") === isA ? STEP : -STEP;
        return { ...row, rating: row.rating + delta, votes: row.votes + 1 };
      }),
    );
  };

  const nextRound = () => {
    setRound((value) => value + 1);
    setVote(null);
    left.reset();
    right.reset();
  };

  const verdict =
    vote === null ? "" : vote === "tie" ? `You called it a tie between ${modelA.name} and ${modelB.name}.` : `You picked ${vote === "A" ? modelA.name : modelB.name}.`;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <div className="grid @4xl:grid-cols-[17rem_1fr]">
        <aside aria-label="Leaderboard and settings" className="flex flex-col gap-4 border-b border-border p-4 @4xl:border-r @4xl:border-b-0">
          <div className="flex flex-col gap-1">
            <h2 id={titleId} className="flex items-center gap-2 text-base font-semibold">
              <ScaleIcon aria-hidden="true" className="size-4 text-chart-2" />
              Model arena
            </h2>
            <p className="text-sm text-muted-foreground">Fernhill staff votes, this month</p>
          </div>
          <Leaderboard standings={standings} />
          <label htmlFor={blindId} className="flex cursor-pointer items-center justify-between gap-3 text-sm">
            Hide model names until I vote
            <Switch id={blindId} checked={blind} onCheckedChange={setBlind} />
          </label>
        </aside>

        <div className="flex min-w-0 flex-col gap-4 p-4">
          <form
            className="flex flex-col gap-2"
            onSubmit={(event) => {
              event.preventDefault();
              run();
            }}
          >
            <div className="flex gap-2">
              <Textarea
                aria-label="Prompt for both models"
                value={prompt}
                rows={2}
                onChange={(event) => setPrompt(event.target.value)}
                onKeyDown={(event) => {
                  if (event.nativeEvent.isComposing || event.keyCode === 229) return;
                  if (event.key === "Enter" && !event.shiftKey) {
                    event.preventDefault();
                    run();
                  }
                }}
                className="max-h-32 min-h-10 flex-1 resize-none"
              />
              <Button type="submit" disabled={left.busy || right.busy || !prompt.trim()}>
                <PlayerPlayFilledIcon aria-hidden="true" className="size-4" />
                Run
              </Button>
            </div>
            <div className="flex flex-wrap gap-1.5" role="group" aria-label="Sample prompts">
              {SAMPLES.map((sample) => (
                <Button
                  key={sample.chip}
                  type="button"
                  variant={prompt === sample.prompt ? "secondary" : "outline"}
                  size="sm"
                  className="h-7"
                  onClick={() => {
                    setPrompt(sample.prompt);
                    run(sample.prompt);
                  }}
                >
                  {sample.chip}
                </Button>
              ))}
            </div>
          </form>

          <div className="grid gap-3 @2xl:grid-cols-2">
            <AnswerPane side="A" name={revealed ? modelA.name : null} hue={modelA.hue} text={textA} shown={left.shown} status={left.status} won={vote === "A"} />
            <AnswerPane side="B" name={revealed ? modelB.name : null} hue={modelB.hue} text={textB} shown={right.shown} status={right.status} won={vote === "B"} />
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <Button variant="ghost" size="sm" disabled={!started || left.busy || right.busy} onClick={() => run()}>
              <RefreshIcon aria-hidden="true" className="size-4" />
              Retry
            </Button>
            <span className="flex-1" />
            {vote === null ? (
              <div role="group" aria-label="Which answer is better?" className="flex flex-wrap gap-2">
                <Button variant="outline" size="sm" disabled={!finished} onClick={() => cast("A")}>
                  A is better
                </Button>
                <Button variant="outline" size="sm" disabled={!finished} onClick={() => cast("tie")}>
                  Tie
                </Button>
                <Button variant="outline" size="sm" disabled={!finished} onClick={() => cast("B")}>
                  B is better
                </Button>
              </div>
            ) : (
              <Button size="sm" onClick={nextRound}>
                Next round
              </Button>
            )}
          </div>
          <p aria-live="polite" className="min-h-5 text-sm text-muted-foreground">
            {verdict}
          </p>
        </div>
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

