import { useCallback, useEffect, useRef } from "react";

/**
 * Keeps a scroll box pinned to its end while new content arrives, until the
 * reader scrolls up. Scrolling back to the end pins it again. Pass any value
 * that changes as content grows as `watch`.
 */
export function useFollowScroll<T extends HTMLElement>(watch: string | number) {
  const ref = useRef<T>(null);
  const pinned = useRef(true);

  const onScroll = useCallback(() => {
    const box = ref.current;
    if (!box) return;
    pinned.current = box.scrollHeight - box.scrollTop - box.clientHeight < 24;
  }, []);

  useEffect(() => {
    const box = ref.current;
    if (box && pinned.current) box.scrollTop = box.scrollHeight;
  }, [watch]);

  /** Pins the box again, such as when the person sends a new message. */
  const pin = useCallback(() => {
    pinned.current = true;
  }, []);

  return { ref, onScroll, pin };
}

