const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });

/**
 * The models ranked by rating, each with a bar in its own colour. Hovering or
 * focusing a row shows it at full colour and fades the others.
 */
export function Leaderboard({ standings }: { standings: Standing[] }) {
  const [hover, setHover] = useState<string | null>(null);
  const sorted = [...standings].sort((a, b) => b.rating - a.rating);
  const low = Math.min(...sorted.map((row) => row.rating)) - 40;
  const high = Math.max(...sorted.map((row) => row.rating));
  return (
    <ol aria-label="Leaderboard" className="flex flex-col gap-0.5" onMouseLeave={() => setHover(null)}>
      {sorted.map((row, index) => {
        const model = modelById(row.id);
        const faded = hover !== null && hover !== row.id;
        const barStyle: VarStyle = { "--w": `${((row.rating - low) / (high - low)) * 100}%` };
        return (
          <li
            key={row.id}
            tabIndex={0}
            onMouseEnter={() => setHover(row.id)}
            onFocus={() => setHover(row.id)}
            onBlur={() => setHover(null)}
            className={cn(
              "relative isolate grid grid-cols-[1rem_minmax(0,6.5rem)_minmax(2rem,1fr)_3rem] items-center gap-2 rounded-md px-2 py-1 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring motion-safe:transition-opacity",
              faded && "opacity-40",
            )}
          >
            <span aria-hidden="true" className={cn("absolute inset-0 -z-10 rounded-md", hover === row.id && "bg-muted/60")} />
            <span className="text-xs text-muted-foreground tabular-nums">{index + 1}</span>
            <span className="truncate font-medium">{model.name}</span>
            <span aria-hidden="true" className="h-1.5 overflow-hidden rounded-full bg-muted">
              <span className={cn("block h-full w-(--w) rounded-full motion-safe:transition-all motion-safe:duration-500", model.hue)} style={barStyle} />
            </span>
            <span className="text-right">
              <RollingText text={WHOLE.format(row.rating)} className="text-sm font-medium" />
              <span className="sr-only">
                rating, {row.votes} votes
              </span>
            </span>
          </li>
        );
      })}
    </ol>
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

